			'src' => 'https://www.sos.alabama.gov/sites/default/files/election-2026/2026-VoterGuide.pdf',
			'checked' => '2026-10-21',
		),
		'mail.who' => array(
			'en' => 'You can vote absentee in Alabama if you:',
