		'mail.cure' => array(
			'en' => 'Check the affidavit envelope before you seal it: your signature, and two witnesses or a notary. Alabama has no way to count a ballot with a deficient envelope.',
			'es' => 'Revisa el sobre con la declaración jurada antes de cerrarlo: tu firma, y dos testigos o un notario. Alabama no tiene forma de contar una boleta con un sobre incompleto.',
			'src' => 'https://www.sos.alabama.gov/sites/default/files/election-2024/AbsenteeElectionManagerGuide.pdf',
			'checked' => '2026-10-26',
		),
		'mail.dropbox' => array(
			'en' => 'Send your ballot by U.S. Mail or a commercial carrier, or hand it in yourself at your county\'s Absentee Election Manager. With an emergency absentee ballot, someone you name can deliver it. No one else can return it for you.',
			'es' => 'Manda tu boleta por el Servicio Postal de EE. UU. o por una empresa de mensajería, o entrégala en persona en la oficina de voto en ausencia de tu condado (Absentee Election Manager). Con una boleta de emergencia para votar en ausencia, una persona que tú designes puede entregarla. Nadie más puede devolverla por ti.',
			'src' => 'https://www.sos.alabama.gov/alabama-votes/voter/absentee-voting',
			'checked' => '2026-10-28',
		),
		'mail.witness' => array(
			'en' => 'Sign the affidavit on your ballot envelope in front of a notary or two witnesses who are 18 or older. Without that, the ballot can\'t be counted. Online or remote notarizing isn\'t allowed.',
			'es' => 'Firma la declaración del sobre de tu boleta frente a un notario o dos testigos de 18 años o más. Sin eso, la boleta no se puede contar. No se permite notarizar en línea ni a distancia.',
