			'checked' => '2026-10-21',
		),
		'polls_rules.gear' => array(
			'en' => 'You can wear campaign buttons or T-shirts into the polling place in Alabama. Just don\'t hang around or leave campaign materials behind. Campaigners have to stay at least 30 feet from the entrance.',
			'es' => 'En Alabama puedes entrar al lugar de votación con botones o camisetas de campaña. Solo no te quedes merodeando ni dejes propaganda de campaña. Quienes hacen campaña deben quedarse a por lo menos 30 pies de la entrada.',
			'src' => 'https://www.sos.alabama.gov/alabama-votes/faqs',
			'checked' => '2026-10-21',
		),
		'polls_rules.phone' => array(
			'en' => 'You can bring your phone if you don\'t disturb other voters. Inside, you can take a picture of your own ballot or of you with it, but no other photos or video, and never of another voter\'s ballot. Take your sticker selfie outside. Nothing official covers photos of an absentee ballot, so ask your county\'s Absentee Election Manager.',
			'es' => 'Puedes llevar tu teléfono si no molestas a los demás votantes. Adentro puedes tomarle una foto a tu propia boleta o tomarte una foto con ella, pero ninguna otra foto ni video, y nunca de la boleta de otro votante. Tómate la selfie con tu sticker afuera. Ninguna fuente oficial habla de fotos de una boleta de voto en ausencia, así que pregunta en la oficina de voto en ausencia de tu condado (Absentee Election Manager).',
			'src' => 'https://www.sos.alabama.gov/alabama-votes/faqs',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'Get in line before 7 p.m. Anyone who tries to join the line after 7 p.m. can\'t vote.',
			'es' => 'Fórmate en la fila antes de las 7 p. m. Quien intente formarse después de las 7 p. m. no puede votar.',
			'src' => 'https://www.sos.alabama.gov/sites/default/files/election-2026/2026-VoterGuide.pdf',
			'checked' => '2026-10-21',
		),
		'sticker.tradition' => array(
			'en' => 'For the November 3, 2026 general election, Alabama\'s Secretary of State released newly designed America 250 I Voted stickers, marking the country\'s 250th anniversary.',
			'es' => 'Para la elección general del 3 de noviembre de 2026, la Secretaría de Estado de Alabama sacó stickers de I Voted con un diseño nuevo de America 250, por los 250 años del país.',
