		'dates.reg_deadline' => array(
			'en' => 'Registration closed Monday, October 5, 2026. Arkansas has no same-day or Election Day registration. Already registered in Arkansas and moved to another county? Contact your county clerk. Transfers of registered voters can be received until the polls close on November 3.',
			'es' => 'El registro cerró el lunes 5 de octubre de 2026. Arkansas no tiene registro el mismo día ni el Día de las Elecciones. ¿Ya estás registrado en Arkansas y te mudaste a otro condado? Comunícate con el secretario de tu condado (county clerk). Los traslados de votantes registrados se pueden recibir hasta que cierren las urnas el 3 de noviembre.',
			'src' => 'https://www.sos.arkansas.gov/uploads/elections/2026_Election_Calendar_Rev._6-2025_.pdf',
			'checked' => '2026-10-28',
		),
		'dates.mail_request' => array(
			'en' => 'Mail, fax and email applications closed Tuesday, October 27. If you qualify to vote absentee, you, a designated bearer or a care facility administrator can still hand in an application at your county clerk\'s office until close of business Friday, October 30. Or vote early in person through 5 p.m. Monday, November 2.',
			'es' => 'Las solicitudes por correo, fax y correo electrónico cerraron el martes 27 de octubre. Si cumples los requisitos para votar en ausencia, tú, un portador designado (designated bearer) o el administrador de un centro de cuidado todavía pueden entregar una solicitud en la oficina del secretario de tu condado (county clerk) hasta el cierre de oficina del viernes 30 de octubre. O vota por anticipado en persona hasta las 5 p. m. del lunes 2 de noviembre.',
			'src' => 'https://www.sos.arkansas.gov/uploads/elections/2026_Election_Calendar_Rev._6-2025_.pdf',
			'checked' => '2026-10-28',
			'until' => '2026-10-30',
			'en_after' => 'Absentee applications by mail and in person are closed. Vote early in person through 5 p.m. on Monday, November 2, or at the polls on Election Day. A voter who is medically unable to get to the polls can still apply through an authorized agent until 1:30 p.m. on Election Day.',
			'es_after' => 'Las solicitudes de boleta de voto en ausencia por correo y en persona ya cerraron. Vota por anticipado en persona hasta las 5 p. m. del lunes 2 de noviembre, o en tu lugar de votación el Día de las Elecciones. Un votante que por razones médicas no puede ir a votar todavía puede pedir su boleta por medio de un agente autorizado (authorized agent) hasta la 1:30 p. m. del Día de las Elecciones.',
		),
		'dates.mail_return' => array(
			'en' => 'A mailed ballot must reach your county clerk\'s office by 7:30 p.m. on Tuesday, November 3, 2026. Delivering it yourself or by a designated bearer? That deadline is close of business Friday, October 30. You can\'t fax or email a ballot. Military and overseas ballots count if the clerk gets them by 5 p.m. Friday, November 13.',
			'es' => 'Una boleta por correo debe llegar a la oficina del secretario de tu condado (county clerk) a más tardar a las 7:30 p. m. del martes 3 de noviembre de 2026. ¿La entregas tú o un portador designado (designated bearer)? El plazo es el cierre de oficina del viernes 30 de octubre. No puedes mandar la boleta por fax ni por correo electrónico. Las boletas militares y del extranjero cuentan si el secretario las recibe a más tardar a las 5 p. m. del viernes 13 de noviembre.',
			'src' => 'https://www.sos.arkansas.gov/uploads/elections/2026_Election_Calendar_Rev._6-2025_.pdf',
			'checked' => '2026-10-28',
			'until' => '2026-10-30',
			'en_after' => 'A mailed ballot must reach your county clerk\'s office by 7:30 p.m. on Tuesday, November 3, 2026. You can\'t fax or email a ballot. Military and overseas ballots count if the clerk gets them by 5 p.m. Friday, November 13.',
			'es_after' => 'Una boleta por correo debe llegar a la oficina del secretario de tu condado (county clerk) a más tardar a las 7:30 p. m. del martes 3 de noviembre de 2026. No puedes mandar la boleta por fax ni por correo electrónico. Las boletas militares y del extranjero cuentan si el secretario las recibe a más tardar a las 5 p. m. del viernes 13 de noviembre.',
		),
		'dates.early_hours' => array(
			'en' => 'Vote early Monday to Friday from 8 a.m. to 6 p.m., or Saturday from 10 a.m. to 4 p.m. Early voting ends at 5 p.m. on Monday, November 2. Off-site early voting hours can vary by county, so check with your county clerk.',
			'es' => 'Vota por anticipado de lunes a viernes de 8 a. m. a 6 p. m., o el sábado de 10 a. m. a 4 p. m. La votación anticipada termina a las 5 p. m. del lunes 2 de noviembre. El horario de los lugares de votación anticipada fuera de la oficina del condado puede variar, así que pregunta en la oficina del secretario de tu condado (county clerk).',
			'src' => 'https://www.sos.arkansas.gov/elections/voter-information/voter-registration-information/voting-in-arkansas',
			'checked' => '2026-10-21',
			'until' => '2026-11-02',
			'en_after' => 'Early voting ended at 5 p.m. on November 2. Vote at your polling site on Election Day, 7:30 a.m. to 7:30 p.m.',
			'es_after' => 'La votación anticipada terminó a las 5 p. m. del 2 de noviembre. Vota en tu lugar de votación el Día de las Elecciones, de 7:30 a. m. a 7:30 p. m.',
		),
		'how.in_person' => array(
