		'id.rule' => 'id_nonphoto',
		'id.accepted' => array(
			'en' => array( 'One photo ID with your name and address: an Arizona driver license, an Arizona non-operating ID card, a tribal ID, or another valid U.S. federal, state or local government ID', 'Or two documents with your name and address, such as a utility bill or a bank or credit union statement dated within 90 days of the election, Arizona vehicle registration, an Arizona vehicle insurance card, a property tax statement, your voter registration card, or mail marked "Official Election Material"', 'Or a photo ID whose address doesn\'t match, a U.S. passport or a U.S. military ID, plus one document from the list above' ),
			'es' => array( 'Una identificación con foto que tenga tu nombre y dirección: licencia de conducir de Arizona, tarjeta de identificación de no conductor de Arizona (non-operating ID), identificación tribal u otra identificación vigente del gobierno federal, estatal o local de EE. UU.', 'O dos documentos con tu nombre y dirección, como un recibo de servicios o un estado de cuenta del banco o de la cooperativa de crédito con fecha dentro de los 90 días antes de la elección, el registro de tu vehículo de Arizona, una tarjeta de seguro de auto de Arizona, un estado de cuenta del impuesto predial, tu tarjeta de registro de votante o correo marcado "Official Election Material" (material electoral oficial)', 'O una identificación con foto cuya dirección no coincida, un pasaporte de EE. UU. o una identificación militar de EE. UU., más un documento de la lista anterior' ),
			'src' => 'https://azsos.gov/elections/voters/voting-elections',
			'checked' => '2026-10-21',
		),
		'id.without' => array(
			'en' => 'No acceptable ID? You vote a conditional provisional ballot. To make it count, show ID to your county recorder by Sunday, November 8. Members of federally recognized tribes can use a tribal ID without an address or photo to cast a provisional ballot.',
			'es' => '¿No tienes una identificación aceptada? Votas con una boleta provisional condicional. Para que cuente, muestra tu identificación al registrador de tu condado (county recorder) a más tardar el domingo 8 de noviembre. Los miembros de tribus reconocidas por el gobierno federal pueden usar una identificación tribal sin dirección ni foto para votar con una boleta provisional.',
			'src' => 'https://azsos.gov/elections/voters/voting-elections',
