		'polls_rules.gear' => array(
			'en' => 'Voters may wear clothing with a political message inside the 75-foot limit. Campaigning there isn\'t allowed: no handing out literature or talking to voters about candidates or issues.',
			'es' => 'Los votantes pueden usar ropa con un mensaje político dentro del límite de 75 pies. Ahí no se permite hacer campaña: nada de repartir propaganda ni hablar con los votantes sobre candidatos o temas de la boleta.',
