		'dates.reg_deadline' => array(
			'en' => 'The regular deadline was Friday, October 16, 2026. Missed it? You can still register and vote the same day during early voting or on Election Day at your town\'s Same Day Registration location. Bring a birth certificate, driver\'s license or Social Security card. If it doesn\'t show your address in town, also bring something that does, such as a utility bill, lease or paycheck.',
			'es' => 'La fecha límite regular fue el viernes 16 de octubre de 2026. ¿Se te pasó? Todavía puedes registrarte y votar el mismo día durante la votación anticipada o el Día de las Elecciones en el lugar de registro el mismo día (Same Day Registration) de tu municipio. Lleva tu acta de nacimiento, licencia de conducir o tarjeta del Seguro Social. Si no muestra tu dirección en el municipio, lleva también algo que sí la muestre, como un recibo de servicios, un contrato de arrendamiento o un talón de pago.',
			'src' => 'https://portal.ct.gov/-/media/sots/electionservices/handbooks/2026/2026-sdr-handbook.pdf',
			'checked' => '2026-10-28',
		),
		'dates.mail_request' => array(
			'en' => 'You can apply for an absentee ballot any time, but it comes back to you by mail, so this close to Election Day voting in person is safer. Six or fewer days before the election, if a sudden illness or disability keeps you from the polls, or you\'re in a hospital or nursing home, use the paper Emergency Application for Absentee Ballot.',
			'es' => 'Puedes solicitar una boleta de voto en ausencia en cualquier momento, pero te llega por correo, así que a estas alturas es más seguro votar en persona. Seis días o menos antes de la elección, si una enfermedad o discapacidad repentina no te deja ir a votar, o estás en un hospital o un asilo de ancianos, usa la solicitud de emergencia en papel (Emergency Application for Absentee Ballot).',
			'src' => 'https://portal.ct.gov/-/media/sots/early-voting/2026-voting-guide/2026_voter_guide-2-final-combined.pdf',
			'checked' => '2026-10-28',
		),
		'dates.mail_return' => array(
			'en' => 'Mailing it or using a drop box? Your Town Clerk must receive it by 8 p.m. on Tuesday, November 3. Bringing it to the Town Clerk yourself? Do it by close of business on Monday, November 2. A family member who lives with you, or the designee of an ill or disabled voter, can hand it in until 8 p.m. on Election Day.',
			'es' => '¿La mandas por correo o la dejas en un buzón de entrega? El secretario municipal (Town Clerk) debe recibirla a más tardar a las 8 p. m. del martes 3 de noviembre. ¿La llevas tú mismo al secretario municipal? Hazlo antes del cierre de la oficina el lunes 2 de noviembre. Un familiar que vive contigo, o la persona designada de un votante enfermo o con discapacidad, puede entregarla hasta las 8 p. m. del Día de las Elecciones.',
			'src' => 'https://portal.ct.gov/-/media/sots/early-voting/2026-voting-guide/2026_voter_guide-2-final-combined.pdf',
			'checked' => '2026-10-28',
		),
		'dates.early_hours' => array(
			'en' => 'Early voting runs 10 a.m. to 6 p.m. every day, weekends included, with longer hours, 8 a.m. to 8 p.m., on Tuesday, October 27, and Thursday, October 29. If you\'re in line by closing time, you can vote.',
			'es' => 'La votación anticipada es de 10 a. m. a 6 p. m. todos los días, incluidos los fines de semana, con horario extendido, de 8 a. m. a 8 p. m., el martes 27 de octubre y el jueves 29 de octubre. Si estás en la fila a la hora de cierre, puedes votar.',
			'src' => 'https://portal.ct.gov/-/media/sots/early-voting/2026-voting-guide/2026_voter_guide-2-final-combined.pdf',
			'checked' => '2026-10-21',
			'until' => '2026-11-01',
			'en_after' => 'Early voting ended November 1. Vote at your assigned polling place on Election Day, 6 a.m. to 8 p.m.',
			'es_after' => 'La votación anticipada terminó el 1 de noviembre. Vota en el lugar de votación que te corresponde el Día de las Elecciones, de 6 a. m. a 8 p. m.',
		),
		'dates.cure' => array(
			'en' => 'Forgot to sign your absentee envelope? Your Town Clerk will try to reach you. You can sign it in person at the Town Clerk\'s office until the polls close at 8 p.m. on Tuesday, November 3, 2026.',
			'es' => '¿Se te olvidó firmar el sobre de tu boleta de voto en ausencia? El secretario municipal (Town Clerk) tratará de comunicarse contigo. Puedes firmarlo en persona en la oficina del secretario municipal hasta que cierren las casillas a las 8 p. m. del martes 3 de noviembre de 2026.',
			'src' => 'https://portal.ct.gov/-/media/sots/electionservices/lead_communications/2026/july/20260720finalmoderatorshandbooksupplement.pdf',
			'checked' => '2026-10-28',
		),
		'how.in_person' => array(
			'en' => 'Vote early at your town\'s designated early voting location, or at your assigned polling place on Election Day. Every town has at least one early voting site, and anyone registered in New Britain, Windham, New Haven, Mansfield or Danbury can also vote early at the state university campus site in that town.',
			'es' => 'Vota por anticipado en el lugar de votación anticipada que designó tu municipio, o en el lugar de votación que te corresponde el Día de las Elecciones. Cada municipio tiene por lo menos un lugar de votación anticipada, y cualquier persona registrada en New Britain, Windham, New Haven, Mansfield o Danbury también puede votar por anticipado en el campus de la universidad estatal de ese municipio.',
			'src' => 'https://portal.ct.gov/-/media/sots/early-voting/2026-voting-guide/2026_voter_guide-2-final-combined.pdf',
			'checked' => '2026-10-28',
		),
		'how.first_time' => array(
			'en' => 'Voting for the first time in Connecticut after registering by mail? If there\'s a mark next to your name on the voter list, show one of these: a current photo ID with your name; a paper or digital copy of a current utility bill, bank statement, government check, paycheck or government document with your name and address; your Connecticut driver\'s license number; or the last four digits of your Social Security number.',
			'es' => '¿Votas por primera vez en Connecticut después de registrarte por correo? Si hay una marca junto a tu nombre en la lista de votantes, muestra una de estas: una identificación vigente con foto y tu nombre; una copia en papel o digital de un recibo de servicios, un estado de cuenta bancario, un cheque del gobierno, un talón de pago o un documento del gobierno actual con tu nombre y dirección; el número de tu licencia de conducir de Connecticut; o los últimos cuatro dígitos de tu número de Seguro Social.',
			'src' => 'https://portal.ct.gov/-/media/sots/electionservices/lead_communications/2026/july/20260720finalmoderatorshandbooksupplement.pdf',
			'checked' => '2026-10-28',
