			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'If you\'re in line by 8 p.m., you can vote, and your vote will be counted.',
			'es' => 'Si estás en la fila a las 8 p. m., puedes votar y tu voto se va a contar.',
			'src' => 'https://portal.ct.gov/-/media/sots/early-voting/2026-voting-guide/2026_voter_guide-2-final-combined.pdf',
			'checked' => '2026-10-21',
		),
		'sticker.tradition' => array(
			'en' => 'For the 2020 election, the 100th anniversary of the 19th Amendment, Connecticut\'s Secretary of the State put out "I Voted" stickers honoring Connecticut women who fought for the vote. Wilton designer Pamela Hovland started the project, and the stickers won a 2020 U.S. Election Assistance Commission award. You can still download them from the Secretary of the State\'s site.',
			'es' => 'Para la elección de 2020, en el centenario de la Enmienda 19, la Secretaría del Estado de Connecticut sacó stickers de "I Voted" en honor a las mujeres de Connecticut que lucharon por el voto. La diseñadora Pamela Hovland, de Wilton, inició el proyecto, y los stickers ganaron un premio de la Comisión de Asistencia Electoral de EE. UU. (U.S. Election Assistance Commission) en 2020. Todavía puedes descargarlos del sitio de la Secretaría del Estado.',
			'src' => 'https://portal.ct.gov/sots/press-releases/previous-years/2021-press-releases/connecticuts-commemorative-suffragist-i-voted-stickers',
			'checked' => '2026-10-28',
		),
		'election_day.hours' => array(
			'en' => 'Polling places are open 6 a.m. to 8 p.m. local time.',
			'es' => 'Los lugares de votación abren de 6 a. m. a 8 p. m., hora local.',
			'src' => 'https://www.cga.ct.gov/current/pub/chap_146.htm',
			'checked' => '2026-10-25',
		),
		'faq.provisional' => array(
			'en' => 'If you registered to vote but your name isn\'t on the voter list, you can vote a provisional ballot. You\'ll sign a statement at the polling place saying you\'re qualified to vote there and haven\'t already voted in this election.',
			'es' => 'Si te registraste para votar pero tu nombre no aparece en la lista de votantes, puedes votar con una boleta provisional. Firmarás una declaración en el lugar de votación de que puedes votar ahí y de que no has votado ya en esta elección.',
			'src' => 'https://portal.ct.gov/-/media/sots/early-voting/2026-voting-guide/2026_voter_guide-2-final-combined.pdf',
			'checked' => '2026-10-21',
		),
		'faq.line' => array(
			'en' => 'You can still vote. As long as you\'re in line by 8 p.m., you can vote, and an election official stands at the end of the line to close it.',
			'es' => 'Todavía puedes votar. Si estás en la fila a las 8 p. m., puedes votar, y un funcionario electoral se pone al final de la fila para cerrarla.',
			'src' => 'https://www.cga.ct.gov/current/pub/chap_146.htm',
			'checked' => '2026-10-21',
