		'dates.reg_deadline' => array(
			'en' => 'The online and mail deadline was October 13. You can still register and vote the same day at any Vote Center, during early voting or on Election Day. Bring proof of your name and current DC address, such as a government photo ID or a utility bill from the last 90 days.',
			'es' => 'La fecha límite para registrarte en línea o por correo fue el 13 de octubre. Todavía puedes registrarte y votar el mismo día en cualquier centro de votación (Vote Center), durante la votación anticipada o el Día de las Elecciones. Lleva un comprobante con tu nombre y tu dirección actual en DC, como una identificación con foto del gobierno o un recibo de servicios de los últimos 90 días.',
			'src' => 'https://www.dcboe.org/voters/register-to-vote/register-update-voter-registration',
			'checked' => '2026-10-28',
		),
		'dates.mail_request' => array(
			'en' => 'You don\'t need to ask. DC mails a ballot to every active registered voter. If yours hasn\'t come, call the DC Board of Elections at (202) 727-2525. If it hasn\'t arrived by Friday, October 30, plan to vote in person.',
			'es' => 'No tienes que pedirla. DC envía por correo una boleta a cada votante registrado activo. Si no te ha llegado, llama a la Junta de Elecciones de DC al (202) 727-2525. Si no te llega a más tardar el viernes 30 de octubre, planea votar en persona.',
			'src' => 'https://www.dcboe.org/getContentAsset/5a9ceeda-114c-4171-810d-1317c9e06b0e/5ebbd046-860b-4ee1-81c8-43d0e3bc446e/_-DCBOE-Voter-Guide-Web-Smaller-File.pdf?language=en',
			'checked' => '2026-10-28',
			'until' => '2026-10-30',
			'en_after' => 'DC mailed a ballot to every active registered voter. If yours didn\'t come, vote in person at any Vote Center.',
			'es_after' => 'DC envió por correo una boleta a cada votante registrado activo. Si no te llegó, vota en persona en cualquier centro de votación (Vote Center).',
		),
		'dates.mail_return' => array(
			'en' => 'Drop box or Vote Center: by 8 p.m. on Tuesday, November 3. Mail: postmarked by November 3 and received by Friday, November 13. The Postal Service doesn\'t always postmark mail the day it picks it up, so mail it early or ask for a hand-stamped postmark at a post office.',
			'es' => 'Buzón de entrega o centro de votación: a más tardar a las 8 p. m. del martes 3 de noviembre. Por correo: con matasellos del 3 de noviembre o antes, y recibida a más tardar el viernes 13 de noviembre. El Servicio Postal no siempre pone el matasellos el mismo día que recoge el correo, así que mándala con tiempo o pide en una oficina de correos que la sellen a mano.',
			'src' => 'https://www.dcboe.org/getContentAsset/5a9ceeda-114c-4171-810d-1317c9e06b0e/5ebbd046-860b-4ee1-81c8-43d0e3bc446e/_-DCBOE-Voter-Guide-Web-Smaller-File.pdf?language=en',
