		'dates.mail_request' => array(
			'en' => 'Your county must receive your application by 11:59 p.m. on Thursday, October 22, 2026. A postmark doesn\'t count. Apply online at IndianaVoters.in.gov, or by mail, email or in person.',
			'es' => 'Tu condado debe recibir tu solicitud a más tardar a las 11:59 p. m. del jueves 22 de octubre de 2026. El matasellos no cuenta. Solicítala en línea en IndianaVoters.in.gov, o por correo postal, correo electrónico o en persona.',
			'src' => 'https://www.in.gov/dA/a5aa6862f1/2026-Calendar-Brochure.FINAL-VERSION.pdf',
			'checked' => '2026-10-28',
			'until' => '2026-10-22',
			'en_after' => 'Mail ballot applications closed at 11:59 p.m. on October 22. Stuck at home by illness or injury, or caring for someone who is? Ask your county clerk by noon Monday, November 2 for a traveling board to bring you a ballot. Everyone else can vote early in person until noon November 2, or at the polls on Election Day.',
			'es_after' => 'Las solicitudes de boleta por correo cerraron a las 11:59 p. m. del 22 de octubre. ¿No puedes salir de casa por una enfermedad o lesión, o cuidas a alguien en esa situación? Pide a la oficina del secretario de tu condado (circuit court clerk), a más tardar al mediodía del lunes 2 de noviembre, que una junta de votación en ausencia (absentee voter board) te lleve una boleta. Los demás pueden votar por anticipado en persona hasta el mediodía del 2 de noviembre, o en su lugar de votación el Día de las Elecciones.',
		),
		'dates.mail_return' => array(
			'en' => 'County election officials must have it by 6 p.m. local time on Tuesday, November 3, 2026. A postmark isn\'t enough, even one dated on or before Election Day.',
			'es' => 'Los funcionarios electorales del condado deben tenerla a más tardar a las 6 p. m., hora local, del martes 3 de noviembre de 2026. No basta con el matasellos, aunque tenga fecha del Día de las Elecciones o antes.',
			'src' => 'https://www.in.gov/sos/elections/voter-information/ways-to-vote/absentee-voting/',
			'checked' => '2026-10-21',
		),
		'dates.early_hours' => array(
			'en' => 'Your county sets early voting days, hours and sites. On Saturday, October 31, the clerk\'s office is open at least 7 hours. A county under 20,000 people may cut that to 4. Early voting ends at noon on Monday, November 2.',
			'es' => 'Tu condado fija los días, horarios y lugares de votación anticipada. El sábado 31 de octubre, la oficina del secretario abre por lo menos 7 horas. Un condado de menos de 20,000 habitantes puede reducirlo a 4. La votación anticipada termina al mediodía del lunes 2 de noviembre.',
			'src' => 'https://www.in.gov/dA/a5aa6862f1/2026-Calendar-Brochure.FINAL-VERSION.pdf',
			'checked' => '2026-10-28',
			'until' => '2026-10-31',
			'en_after' => 'Early voting ends at noon on Monday, November 2. Your county sets the hours and sites. After that, vote at the polls on Election Day, 6 a.m. to 6 p.m. local time.',
			'es_after' => 'La votación anticipada termina al mediodía del lunes 2 de noviembre. Tu condado fija los horarios y lugares. Después, vota en tu lugar de votación el Día de las Elecciones, de 6 a. m. a 6 p. m., hora local.',
		),
		'how.in_person' => array(
