		'id.expired' => array(
			'en' => 'Your photo ID can be current or expired after November 5, 2024. It must come from Indiana or the U.S. government. School and college IDs don\'t count. The address on it doesn\'t have to match your registration.',
			'es' => 'Tu identificación con foto puede estar vigente o haber vencido después del 5 de noviembre de 2024. Debe ser emitida por Indiana o por el gobierno de EE. UU. Las identificaciones escolares y universitarias no cuentan. La dirección no tiene que coincidir con la de tu registro.',
			'src' => 'https://www.in.gov/sos/elections/voter-information/photo-id-law/',
			'checked' => '2026-10-28',
		),
		'id.without' => array(
			'en' => 'No ID that meets the rules? You can vote a provisional ballot. Then, by noon on Friday, November 13 (10 days after the election), bring the ID to your county election board or sign an affidavit that an exemption applies to you. Indiana photo ID cards are free at any BMV branch.',
			'es' => '¿No tienes una identificación que cumpla las reglas? Puedes votar con una boleta provisional. Después, a más tardar al mediodía del viernes 13 de noviembre (10 días después de la elección), lleva la identificación a la junta electoral de tu condado o firma una declaración jurada de que te aplica una excepción. La tarjeta de identificación con foto de Indiana es gratis en cualquier oficina del BMV.',
			'src' => 'https://www.in.gov/sos/elections/voter-information/photo-id-law/',
			'checked' => '2026-10-28',
		),
		'mail.who' => array(
			'en' => 'You can vote absentee by mail in Indiana if you can mark and sign your own ballot and you:',
			'es' => 'Puedes votar en ausencia por correo en Indiana si puedes marcar y firmar tu propia boleta y:',
			'src' => 'https://www.in.gov/sos/elections/voter-information/ways-to-vote/absentee-voting/',
