		'mail.who_list' => array(
			'en' => array( 'expect to be out of your county for all 12 hours the polls are open (6 a.m. to 6 p.m.)', 'have a disability', 'are 65 or older', 'have official election duties outside your precinct', 'are scheduled to work at your regular job for all 12 hours the polls are open', 'will be confined by illness or injury, or caring for someone who is, for all 12 hours the polls are open', 'can\'t vote because of a religious discipline or holiday during all 12 hours the polls are open', 'are in the state\'s address confidentiality program', 'are in the military or a public safety officer', 'have no transportation to the polls' ),
			'es' => array( 'esperas estar fuera de tu condado durante las 12 horas que abren las urnas (de 6 a. m. a 6 p. m.)', 'tienes una discapacidad', 'tienes 65 años o más', 'tienes funciones electorales oficiales fuera de tu precinto', 'tienes programado trabajar en tu empleo habitual durante las 12 horas que abren las urnas', 'vas a estar en cama por enfermedad o lesión, o cuidando a alguien en esa situación, durante las 12 horas que abren las urnas', 'no puedes votar por una disciplina o festividad religiosa durante las 12 horas que abren las urnas', 'estás en el programa estatal de confidencialidad de domicilio', 'eres militar o agente de seguridad pública', 'no tienes transporte para ir a votar' ),
			'src' => 'https://www.in.gov/sos/elections/voter-information/ways-to-vote/absentee-voting/',
			'checked' => '2026-10-21',
