		'mail.cure' => array(
			'en' => 'Forgot to sign your envelope, made a mistake or got the wrong ballot? Before Election Day, file an ABS-5 form with your county election officials to fix it.',
			'es' => '¿Se te olvidó firmar el sobre, te equivocaste o te llegó la boleta equivocada? Antes del Día de las Elecciones, presenta un formulario ABS-5 ante los funcionarios electorales de tu condado para corregirlo.',
			'src' => 'https://www.in.gov/sos/elections/voter-information/ways-to-vote/absentee-voting/',
			'checked' => '2026-10-21',
		),
		'mail.dropbox' => array(
			'en' => 'You can hand-deliver your finished ballot to your county election board, including at an early voting site, by 6 p.m. on Election Day. Only you, a household or family member, your attorney-in-fact or a bonded courier can drop it off. Anyone but you fills out an ABS-19 affidavit.',
			'es' => 'Puedes entregar en persona tu boleta terminada a la junta electoral de tu condado, incluso en un lugar de votación anticipada, a más tardar a las 6 p. m. del Día de las Elecciones. Solo tú, alguien de tu hogar o de tu familia, tu apoderado (attorney-in-fact) o un mensajero con fianza (bonded courier) pueden entregarla. Cualquiera que no seas tú llena una declaración ABS-19.',
			'src' => 'https://www.in.gov/sos/elections/voter-information/ways-to-vote/absentee-voting/',
			'checked' => '2026-10-28',
		),
		'mail.witness' => array(
			'en' => 'Mark your ballot yourself and sign the ballot security envelope. No one can help you mark a mail ballot. Someone other than your employer or union representative can help you seal the envelope if they fill out the affidavit of assistance. If you need help marking your ballot, ask your county about voting before a traveling board instead.',
			'es' => 'Marca tu boleta tú mismo y firma el sobre de seguridad. Nadie puede ayudarte a marcar una boleta por correo. Alguien que no sea tu empleador ni tu representante sindical puede ayudarte a cerrar el sobre si llena la declaración de asistencia (affidavit of assistance). Si necesitas ayuda para marcar tu boleta, pregunta en tu condado por votar ante una junta de votación en ausencia (absentee voter board).',
			'src' => 'https://www.in.gov/sos/elections/voter-information/ways-to-vote/absentee-voting/',
			'checked' => '2026-10-28',
		),
		'polls_rules.gear' => array(
			'en' => 'Leave the campaign shirts, buttons and signs at home. Clothing or buttons naming a party, a candidate or an elected official, or backing a ballot question, count as electioneering inside the polls and the 50-foot chute leading in. A poll worker may ask you to cover up. If you don\'t, you still get to vote.',
			'es' => 'Deja en casa las camisetas, botones y letreros de campaña. La ropa o los botones que nombran a un partido, a un candidato o a un funcionario electo, o que apoyan una pregunta de la boleta, cuentan como hacer campaña dentro del lugar de votación y en el pasillo de 50 pies que lleva a la entrada. Un trabajador electoral puede pedirte que los cubras. Si no lo haces, igual puedes votar.',
			'src' => 'https://www.in.gov/dA/a8ee46432d/2026-Election-Day-Handbook.pdf',
			'checked' => '2026-10-28',
		),
		'polls_rules.phone' => array(
			'en' => 'A federal court blocked Indiana\'s ban on photos of your own ballot in 2017, and the state didn\'t appeal. You can use your phone at the polls as long as you don\'t campaign or have a loud, disruptive conversation.',
			'es' => 'Un tribunal federal bloqueó en 2017 la prohibición de Indiana de tomarle fotos a tu propia boleta, y el estado no apeló. Puedes usar tu teléfono en el lugar de votación siempre que no hagas campaña ni tengas una conversación ruidosa que moleste.',
			'src' => 'https://www.fjc.gov/sites/default/files/materials/09/EE-CO-1-16-cv-2627-Hill.pdf',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'Polls close at 6 p.m. local time. If you\'re in line by then, stay in line. You can still vote.',
			'es' => 'Los lugares de votación cierran a las 6 p. m., hora local. Si estás en la fila a esa hora, no te salgas. Todavía puedes votar.',
			'src' => 'https://www.in.gov/dA/a8ee46432d/2026-Election-Day-Handbook.pdf',
			'checked' => '2026-10-28',
		),
		'sticker.tradition' => array(
			'en' => 'In 2024 the Indiana Secretary of State held an I Voted sticker contest for students in kindergarten through 12th grade. The first-place design from each grade group was chosen for the stickers handed out on Election Day, November 5, 2024.',
			'es' => 'En 2024, la Secretaría de Estado de Indiana organizó un concurso de stickers de I Voted para estudiantes de kínder a 12.º grado. El diseño ganador de cada grupo de grados se eligió para los stickers que se repartieron el Día de las Elecciones, el 5 de noviembre de 2024.',
