		'id.without' => array(
			'en' => 'Asked for ID and can\'t show it? If you\'re voting for the first time, you vote a provisional ballot and come back with ID before the polls close. For any other reason, you vote a challenged ballot. It\'s cast as normal and only looked at in a recount, court order or audit.',
			'es' => '¿Te piden identificación y no puedes mostrarla? Si votas por primera vez, votas con una boleta provisional y regresas con tu identificación antes de que cierren los lugares de votación. Por cualquier otra razón, votas con una boleta impugnada (challenged ballot). Se deposita como cualquier otra y solo se revisa si hay un reconteo, una orden judicial o una auditoría.',
			'src' => 'https://www.sec.state.ma.us/divisions/elections/voting-information/identification-requirements.htm',
			'checked' => '2026-10-21',
		),
		'mail.who' => array(
			'en' => 'Any registered voter can vote by mail, no reason needed. Apply online at VoteInMA.com, with the application mailed to every voter, or by email or fax with your handwritten signature.',
			'es' => 'Cualquier votante registrado puede votar por correo, sin dar una razón. Solicítalo en línea en VoteInMA.com, con la solicitud que se le envió a cada votante, o por correo electrónico o fax con tu firma a mano.',
