			'checked' => '2026-10-21',
		),
		'polls_rules.gear' => array(
			'en' => 'Leave campaign signs, posters and flyers behind. They aren\'t allowed in the polling place, the building or on its grounds, or within 150 feet of the entrance door. The same rule applies at early voting sites.',
			'es' => 'Deja afuera los letreros, carteles y volantes de campaña. No se permiten en el lugar de votación, en el edificio ni en su terreno, ni a menos de 150 pies de la puerta de entrada. La misma regla aplica en los lugares de votación anticipada.',
			'src' => 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleVIII/Chapter54/Section65',
			'checked' => '2026-10-21',
		),
		'polls_rules.phone' => array(
			'en' => 'Massachusetts law makes it a crime to let anyone see how you marked your ballot for a purpose the law doesn\'t allow. So don\'t share a photo of your marked ballot, whether you voted at the polls or by mail. No official source says whether you can take a photo you keep to yourself, so ask a poll worker first. Share your sticker instead.',
			'es' => 'En Massachusetts es un delito dejar que alguien vea cómo marcaste tu boleta con un fin que la ley no permite. Así que no compartas una foto de tu boleta marcada, ya sea que votaste en persona o por correo. Ninguna fuente oficial dice si puedes tomar una foto que guardes solo para ti, así que primero pregúntale a un trabajador electoral. Mejor comparte tu sticker.',
			'src' => 'https://malegislature.gov/Laws/GeneralLaws/PartI/TitleVIII/Chapter56/Section25',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
