		'mail.who' => array(
			'en' => 'Any registered voter can vote absentee, no reason needed. Check the box on your application to join the permanent list and get a ballot for every election.',
			'es' => 'Cualquier votante registrado puede votar en ausencia, sin dar una razón. Marca la casilla en tu solicitud para entrar a la lista permanente y recibir una boleta en cada elección.',
