		'mail.track_url' => 'https://mvic.sos.state.mi.us/Voter/Index',
		'mail.cure' => array(
			'en' => 'If your signature is missing or doesn\'t match, your clerk will reach you by phone, email or text, or by mail if they have no other way. Your clerk must get the cure form back, electronically, in person or by mail, by 5 p.m. on Friday, November 6.',
			'es' => 'Si falta tu firma o no coincide, tu secretario (clerk) se comunicará contigo por teléfono, correo electrónico o mensaje de texto, o por correo postal si no tiene otra forma. Tu secretario debe recibir el formulario de corrección, por vía electrónica, en persona o por correo, a más tardar a las 5 p. m. del viernes 6 de noviembre.',
			'src' => 'https://www.legislature.mi.gov/Laws/MCL?objectName=MCL-168-766a',
			'checked' => '2026-10-28',
		),
		'mail.dropbox' => array(
			'en' => 'Use one of your clerk\'s drop boxes by 8 p.m. on Election Day. You can also put your finished absentee ballot straight into the tabulator at your early voting site. On Election Day you can do the same at your polling place, except in Detroit, where absentee ballots go to a drop box or the clerk\'s office.',
			'es' => 'Usa uno de los buzones de entrega de tu secretario (clerk) a más tardar a las 8 p. m. del Día de las Elecciones. También puedes meter tu boleta de voto en ausencia ya llenada directamente en la máquina de conteo de tu centro de votación anticipada. El Día de las Elecciones puedes hacer lo mismo en tu lugar de votación, menos en Detroit, donde las boletas de voto en ausencia van a un buzón de entrega o a la oficina del secretario.',
			'src' => 'https://www.michigan.gov/sos/elections/voting/absentee-voting',
			'checked' => '2026-10-28',
		),
		'mail.witness' => array(
			'en' => 'Sign and date the return envelope in the space provided, using the signature on your driver\'s license, state ID or voter registration. Made a mistake, like signing in the wrong place? Ask your clerk for a new ballot.',
			'es' => 'Firma y pon la fecha en el sobre de devolución, en el espacio indicado, con la firma de tu licencia de conducir, identificación estatal o registro de votante. ¿Te equivocaste, por ejemplo firmaste en el lugar equivocado? Pídele una boleta nueva al secretario.',
			'src' => 'https://www.michigan.gov/sos/elections/voting/absentee-voting',
			'checked' => '2026-10-21',
		),
		'polls_rules.gear' => array(
			'en' => 'Leave the campaign shirts, hats, pins and stickers at home. Michigan bans election or campaign clothing and accessories inside a polling place or within 100 feet of it. If you show up in a shirt or button with election images or slogans, you\'ll be asked to cover or remove it.',
			'es' => 'Deja en casa las camisetas, gorras, botones y calcomanías de campaña. Michigan prohíbe la ropa y los accesorios electorales o de campaña dentro de un lugar de votación o a menos de 100 pies. Si llegas con una camiseta o un botón con imágenes o lemas electorales, te pedirán que lo cubras o te lo quites.',
			'src' => 'https://www.michigan.gov/sos/elections/voting/vote-on-election-day',
			'checked' => '2026-10-21',
		),
		'polls_rules.phone' => array(
			'en' => 'You can take a picture of your own ballot in the voting booth. You can\'t hold your ballot up for a selfie or take other photos in the voting area, and don\'t share a picture of your voted ballot within 100 feet of the polling place. Take your sticker selfie outside. The state\'s guidance doesn\'t address photos of an absentee ballot at home.',
			'es' => 'Puedes tomarle una foto a tu propia boleta en la cabina de votación. No puedes levantar tu boleta para una selfie ni tomar otras fotos en el área de votación, y no compartas una foto de tu boleta votada a menos de 100 pies del lugar de votación. Tómate la selfie con tu sticker afuera. La guía del estado no habla de fotos de una boleta de voto en ausencia en casa.',
			'src' => 'https://www.michigan.gov/sos/faqs/elections-and-campaign-finance/elections-and-voting',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'Polls close at 8 p.m. If you\'re in line by then, stay put. You\'ll be allowed to vote. The same goes at closing time on each day of early voting.',
			'es' => 'Los lugares de votación cierran a las 8 p. m. Si estás en la fila a esa hora, no te salgas. Te dejarán votar. Lo mismo aplica a la hora de cierre de cada día de votación anticipada.',
			'src' => 'https://www.legislature.mi.gov/Laws/MCL?objectName=MCL-168-720',
			'checked' => '2026-10-21',
		),
		'sticker.tradition' => array(
			'en' => 'Michigan\'s 2026 I Voted stickers come from a statewide contest run by the Michigan Department of State. More than 2,000 designs came in, the public voted on 30 finalists in each category, and nine designs won. In elementary and middle school, Aryana of Berrien Springs, Aleymi of Romulus and Naia of Detroit won with a "Let me sleep" sticker, a frog and a space bunny. In high school, Lenore of Saginaw, Ahmad of Dearborn Heights and Keirsten of Remus won with a Michigan license plate, a Michigan landscape and the Edmund Fitzgerald. In general entry, Maddie Tallman, Lisa Damesworth and Hilarie Williams won with "No yeah," Superman ice cream and construction barrels. Local election clerks can order the winning stickers for November, so ask yours which ones they hand out.',
			'es' => 'Los stickers de I Voted 2026 de Michigan salen de un concurso estatal del Departamento de Estado de Michigan (Michigan Department of State). Llegaron más de 2,000 diseños, el público votó entre 30 finalistas de cada categoría y ganaron nueve. En primaria y secundaria, ganaron Aryana de Berrien Springs, Aleymi de Romulus y Naia de Detroit, con un sticker "Let me sleep" (déjame dormir), una rana y un conejo espacial. En preparatoria, ganaron Lenore de Saginaw, Ahmad de Dearborn Heights y Keirsten de Remus, con una placa de Michigan, un paisaje de Michigan y el Edmund Fitzgerald. En la categoría general, ganaron Maddie Tallman, Lisa Damesworth y Hilarie Williams, con "No yeah", el helado Superman y barriles de construcción. Los secretarios locales (clerks) pueden pedir los stickers ganadores para noviembre, así que pregunta al tuyo cuáles reparten.',
			'src' => 'https://www.michigan.gov/sos/elections/voting/i-voted-sticker-contest',
			'checked' => '2026-10-28',
		),
		'sticker.mail' => array(
			'en' => 'Look in your ballot envelope. In the City of Northville, every absentee ballot comes with voting instructions and an "I Voted" sticker. Other clerks decide for themselves.',
			'es' => 'Revisa el sobre de tu boleta. En la ciudad de Northville, cada boleta de voto en ausencia llega con instrucciones y un sticker de "I Voted". Los demás secretarios municipales deciden por su cuenta.',
			'src' => 'https://www.cityofnorthvillemi.gov/m/faq',
			'checked' => '2026-10-23',
		),
		'election_day.hours' => array(
			'en' => 'Polling places are open 7 a.m. to 8 p.m. local time.',
			'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m., hora local.',
			'src' => 'https://www.legislature.mi.gov/Laws/MCL?objectName=mcl-168-720',
			'checked' => '2026-10-25',
