			'en' => 'If your ballot is rejected more than five days before the election, you\'ll get a replacement ballot in the mail with the reason. Closer to Election Day, election officials will try to contact you.',
			'es' => 'Si rechazan tu boleta más de cinco días antes de la elección, te mandarán por correo una boleta de reemplazo con el motivo. Más cerca del Día de las Elecciones, las autoridades electorales tratarán de comunicarse contigo.',
			'src' => 'https://www.sos.mn.gov/elections-voting/how-elections-work/absentee-ballot-process/',
			'checked' => '2026-10-21',
		),
		'mail.dropbox' => array(
			'en' => 'Some counties and cities have secure drop boxes you can use any time. On Election Day, get your ballot to a drop box or the office that sent it by 5 p.m. Someone else can drop it off for you. One person can return ballots for up to three voters and must show ID with their name and signature.',
			'es' => 'Algunos condados y ciudades tienen buzones de entrega seguros que puedes usar a cualquier hora. El Día de las Elecciones, lleva tu boleta a un buzón o a la oficina que te la envió a más tardar a las 5 p. m. Otra persona puede entregarla por ti. Una persona puede entregar boletas de hasta tres votantes y tiene que mostrar una identificación con su nombre y firma.',
			'src' => 'https://www.sos.mn.gov/elections-voting/other-ways-to-vote/return-your-ballot/',
			'checked' => '2026-10-28',
		),
		'mail.witness' => array(
			'en' => 'Find a witness before you vote your ballot: any U.S. citizen who will be 18 by Election Day, or a notary. Your witness needs to see your blank ballot first, and you both fill out the white signature envelope.',
			'es' => 'Busca un testigo antes de votar tu boleta: cualquier ciudadano de EE. UU. que tenga 18 años para el Día de las Elecciones, o un notario. Tu testigo tiene que ver tu boleta en blanco primero, y los dos llenan el sobre blanco de firma.',
			'src' => 'https://www.sos.mn.gov/elections-voting/other-ways-to-vote/vote-by-mail-in-us/',
			'checked' => '2026-10-21',
		),
		'polls_rules.gear' => array(
			'en' => 'Cover up or take off campaign shirts and buttons inside the polling place. Minnesota bans wearing anything about a candidate, party or ballot question on that day\'s ballot there, and no one can campaign within 100 feet of the building.',
			'es' => 'Tapa o quítate las camisetas y botones de campaña dentro del lugar de votación. Minnesota prohíbe llevar ahí cualquier cosa sobre un candidato, un partido o una propuesta de la boleta de ese día, y nadie puede hacer campaña a menos de 100 pies del edificio.',
			'src' => 'https://www.sos.mn.gov/elections-voting/election-day-voting/polling-place-rules/',
			'checked' => '2026-10-21',
		),
		'polls_rules.phone' => array(
			'en' => 'No Minnesota law strictly bans taking photos of your own voting in the polling place, but the Secretary of State discourages it. Showing your marked ballot to others is against the law, and a photo or video of it could break that rule. We found no official rule on photos of a mail ballot at home. Save the sticker selfie for outside.',
			'es' => 'Ninguna ley de Minnesota prohíbe del todo tomar fotos de tu propio voto en el lugar de votación, pero la Secretaría de Estado lo desaconseja. Mostrar tu boleta marcada a otras personas va contra la ley, y una foto o video de ella podría violar esa regla. No encontramos ninguna regla oficial sobre fotos de una boleta por correo en casa. Deja la selfie con el sticker para afuera.',
			'src' => 'https://www.sos.mn.gov/elections-voting/election-day-voting/polling-place-rules/',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'Get in line by 8 p.m. on Election Day and you can vote, even if you reach the front after 8.',
			'es' => 'Si estás en la fila a las 8 p. m. del Día de las Elecciones, puedes votar, aunque llegues al frente después de las 8.',
			'src' => 'https://www.sos.mn.gov/elections-voting/election-day-voting/voting-hours/',
			'checked' => '2026-10-21',
		),
		'sticker.tradition' => array(
			'en' => 'Minnesota\'s I voted sticker is written into state law: it says "I VOTED," and nothing more. Election officials can give one to you when you put your ballot in the ballot box, and to people who vote by mail too.',
			'es' => 'El sticker de "I voted" de Minnesota está escrito en la ley estatal: dice "I VOTED", y nada más. Las autoridades electorales te pueden dar uno cuando metes tu boleta en la urna, y también a quienes votan por correo.',
			'src' => 'https://www.revisor.mn.gov/statutes/cite/204B.49',
			'checked' => '2026-10-21',
		),
		'election_day.hours' => array(
			'en' => 'Polling places are open 7 a.m. to 8 p.m., and some small towns can open later, as late as 10 a.m.',
			'es' => 'Los lugares de votación abren de 7 a. m. a 8 p. m., y algunos pueblos pequeños pueden abrir más tarde, hasta las 10 a. m.',
			'src' => 'https://www.revisor.mn.gov/statutes/cite/204C.05',
			'checked' => '2026-10-25',
			'varies' => true,
		),
		'faq.line' => array(
			'en' => 'You can still vote. If you\'re in line by 8 p.m., you get to vote, even if you reach the front after 8.',
			'es' => 'Todavía puedes votar. Si estás en la fila a las 8 p. m., puedes votar, aunque llegues al frente después de las 8.',
			'src' => 'https://www.sos.mn.gov/elections-voting/election-day-voting/voting-hours/',
			'checked' => '2026-10-21',
		),
		'faq.track' => array(
			'en' => 'Use the state\'s Track your ballot tool to see when your ballot was mailed to you, when it came back and whether it was accepted.',
			'es' => 'Usa la herramienta del estado para seguir tu boleta (Track your ballot) para ver cuándo te mandaron la boleta, cuándo la recibieron y si la aceptaron.',
			'src' => 'https://www.sos.mn.gov/elections-voting/other-ways-to-vote/vote-by-mail-in-us/',
			'checked' => '2026-10-21',
		),
		'faq.late_mail' => array(
			'en' => 'Within a week of Election Day, the Secretary of State says to drop it off instead. A mailed ballot must arrive by 8 p.m. on November 3, and a postmark doesn\'t count. Drop it at the office that sent it, or its drop box, by 5 p.m. that day.',
			'es' => 'A una semana del Día de las Elecciones, la Secretaría de Estado recomienda entregarla en persona. Una boleta enviada por correo debe llegar a más tardar a las 8 p. m. del 3 de noviembre, y el matasellos no cuenta. Entrégala en la oficina que te la envió, o en su buzón de entrega, a más tardar a las 5 p. m. de ese día.',
			'src' => 'https://www.sos.mn.gov/elections-voting/other-ways-to-vote/return-your-ballot/',
			'checked' => '2026-10-28',
		),
	),
