		'mail.cure' => array(
			'en' => 'Fill out every statement on your ballot envelope before you send it. An absentee ballot with an unfinished envelope statement is rejected.',
			'es' => 'Llena todas las declaraciones del sobre de tu boleta antes de enviarla. Se rechaza una boleta de voto en ausencia si las declaraciones del sobre no están completas.',
			'src' => 'https://revisor.mo.gov/main/OneSection.aspx?section=115.295',
			'checked' => '2026-10-26',
		),
		'mail.dropbox' => array(
			'en' => 'Missouri law bans drop boxes for absentee ballots. Mail yours, bring it back yourself, or have a relative bring it in person. The law allows a parent, child, sibling, grandparent or grandchild, or one of those relatives by marriage.',
			'es' => 'La ley de Missouri prohíbe los buzones de entrega para las boletas de voto en ausencia. Mándala por correo, entrégala tú o pide a un familiar que la entregue en persona. La ley permite a tu padre o madre, hijo o hija, hermano o hermana, abuelo o abuela, nieto o nieta, o a esos mismos familiares por matrimonio.',
			'src' => 'https://revisor.mo.gov/main/OneSection.aspx?section=115.291',
			'checked' => '2026-10-28',
		),
		'mail.witness' => array(
			'en' => 'Most mailed absentee ballots need the envelope statement signed in front of a notary. You can skip the notary if you\'re voting absentee because of illness or disability, you\'re on your election office\'s permanent disability list, or you\'re a military or overseas voter. A notary can\'t charge you to notarize an absentee ballot.',
			'es' => 'La mayoría de las boletas de voto en ausencia por correo necesitan que firmes la declaración del sobre frente a un notario. No necesitas notario si votas en ausencia por enfermedad o discapacidad, si estás en la lista de discapacidad permanente de tu oficina electoral o si eres votante militar o en el extranjero. Un notario no te puede cobrar por notarizar una boleta de voto en ausencia.',
			'src' => 'https://revisor.mo.gov/main/OneSection.aspx?section=115.283',
			'checked' => '2026-10-28',
		),
		'polls_rules.gear' => array(
			'en' => 'Keep campaign gear away from the door. On Election Day and during absentee voting, Missouri bans electioneering, handing out campaign literature and posting signs inside the building with the polling place or within 25 feet of its door. Your election office can post notice widening the zone to 50 feet, but signs and candidates can still be 25 feet away.',
			'es' => 'Mantén la propaganda lejos de la puerta. El Día de las Elecciones y durante la votación en ausencia, Missouri prohíbe hacer campaña, repartir propaganda electoral y poner letreros dentro del edificio del lugar de votación o a menos de 25 pies de su puerta. Tu oficina electoral puede publicar un aviso para ampliar la zona a 50 pies, pero los letreros y los candidatos pueden seguir a 25 pies.',
			'src' => 'https://revisor.mo.gov/main/OneSection.aspx?section=115.637',
			'checked' => '2026-10-28',
		),
		'polls_rules.phone' => array(
			'en' => 'Missouri law doesn\'t address phones or photos at the polls, and we found no Secretary of State rule on them. The law does make it an offense to let anyone see your ballot so they know how you voted, so don\'t share a photo of your marked ballot. Ask a poll worker before you take any photo inside.',
			'es' => 'La ley de Missouri no habla de celulares ni de fotos en el lugar de votación, y no encontramos ninguna regla de la Secretaría de Estado sobre eso. La ley sí castiga dejar que alguien vea tu boleta para que sepa cómo votaste, así que no compartas una foto de tu boleta marcada. Pregunta a un trabajador electoral antes de tomar cualquier foto adentro.',
			'src' => 'https://revisor.mo.gov/main/OneSection.aspx?section=115.637',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'If you\'re in line at 7 p.m. when the polls close, you have the right to vote.',
			'es' => 'Si estás en la fila a las 7 p. m., cuando cierran las urnas, tienes derecho a votar.',
			'src' => 'https://www.sos.mo.gov/elections/goVoteMissouri/howtovote',
			'checked' => '2026-10-21',
		),
		'sticker.tradition' => array(
			'en' => 'In Boone County, high school students design the sticker. More than 40 students sent in over 70 designs. The one picked for the 2026 and 2027 elections is by Grace, an 11th grader at Rock Bridge High School.',
			'es' => 'En el condado de Boone, estudiantes de preparatoria diseñan el sticker. Más de 40 estudiantes enviaron más de 70 diseños. El elegido para las elecciones de 2026 y 2027 es de Grace, estudiante de 11.º grado de Rock Bridge High School.',
