		'dates.reg_deadline' => array(
			'en' => 'Regular registration closed Monday, October 5, 2026. You can still register late, in person, at your county election office through 8 p.m. on Election Day, November 3. Late registration pauses at noon on Monday, November 2, and reopens on Election Day. You have to pick up your ballot in person, and hours vary by county.',
