			'checked' => '2026-10-28',
		),
		'polls_rules.gear' => array(
			'en' => 'Leave the campaign buttons and badges at home. Montana bans wearing or showing any badge, button or insignia for a candidate or ballot issue where you vote, and bans electioneering within 100 feet of the building entrance.',
			'es' => 'Deja en casa los botones e insignias de campaña. Montana prohíbe llevar o mostrar cualquier insignia, botón o distintivo a favor o en contra de un candidato o una propuesta en el lugar donde votas, y prohíbe hacer campaña a menos de 100 pies de la entrada del edificio.',
			'src' => 'https://mca.legmt.gov/bills/mca/title_0130/chapter_0350/part_0020/section_0110/0130-0350-0020-0110.html',
			'checked' => '2026-10-21',
		),
		'polls_rules.phone' => array(
			'en' => 'You can take a photo of yourself with your own marked ballot and share it. The Commissioner of Political Practices says that doesn\'t break Montana law, as long as you don\'t disrupt voting. Don\'t photograph other voters\' ballots, and follow election officials\' directions about where to take it.',
			'es' => 'Puedes tomarte una foto con tu propia boleta marcada y compartirla. El Comisionado de Prácticas Políticas de Montana (Commissioner of Political Practices) dice que eso no viola la ley de Montana, siempre que no interrumpas la votación. No tomes fotos de las boletas de otros votantes, y sigue las indicaciones de los funcionarios electorales sobre dónde tomarla.',
			'src' => 'https://politicalpractices.mt.gov/_docs/2018-Advisory-Opinions/2018-AO-002-Ballot-Selfies-Final.pdf',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'In line at 8 p.m. at your polling place or the election office? Stay in line. You can still vote.',
