			'es' => 'Si eres un votante que necesita identificación ("Need ID") y no puedes mostrarla, votarás con una boleta provisional de papel. Para que cuente, entrega una copia de tu identificación al comisionado de registro de tu condado (Commissioner of Registration) antes del cierre de oficinas del jueves 5 de noviembre.',
			'src' => 'https://www.nj.gov/state/elections/assets/pdf/posters-bill-of-rights/2026-11-bill-of-rights-poster-english.pdf',
			'checked' => '2026-10-21',
		),
		'mail.who' => array(
