		'polls_rules.gear' => array(
			'en' => 'You can wear your campaign shirt, hat, button or sticker when you go in to vote. Within 40 feet of a polling place entrance, no one may loiter, hand out campaign material or try to sway anyone\'s vote.',
			'es' => 'Puedes llevar tu camiseta, gorra, botón o sticker de campaña cuando entres a votar. A menos de 40 pies de la entrada de un lugar de votación, nadie puede merodear, repartir material de campaña ni tratar de influir en el voto de alguien.',
			'src' => 'https://law.lis.virginia.gov/vacode/title24.2/chapter6/section24.2-604/',
			'checked' => '2026-10-28',
		),
		'polls_rules.phone' => array(
			'en' => 'You can use your phone inside the polling place. In a 2016 opinion, Virginia\'s Attorney General said state law doesn\'t ban photographing your own ballot, and voters may take photos in the polling place when it doesn\'t break election law. You can\'t use your phone to get voting help from someone outside. No official source covers photos of a mail ballot, so ask your general registrar if you\'re unsure.',
			'es' => 'Puedes usar tu teléfono dentro del lugar de votación. En una opinión de 2016, la Fiscalía General (Attorney General) de Virginia dijo que la ley estatal no prohíbe tomarle foto a tu propia boleta, y que los votantes pueden tomar fotos en el lugar de votación siempre que no violen la ley electoral. No puedes usar tu teléfono para que alguien de afuera te ayude a votar. Ninguna fuente oficial habla de fotos de una boleta por correo, así que si tienes dudas, pregunta en la oficina de registro de tu localidad (general registrar).',
			'src' => 'https://www.oag.state.va.us/files/Opinions/2016/16-038_Bell_Lind_issued.pdf',
			'checked' => '2026-10-28',
		),
		'polls_rules.line' => array(
			'en' => 'In line at your polling place at 7 p.m.? Stay in line. You can still vote; people who arrive later can\'t.',
			'es' => '¿Estás en la fila de tu lugar de votación a las 7 p. m.? No te salgas. Todavía puedes votar; quien llegue después ya no puede.',
			'src' => 'https://law.lis.virginia.gov/vacode/title24.2/chapter6/section24.2-603/',
			'checked' => '2026-10-26',
		),
		'sticker.early' => array(
