		'faq.provisional' => array(
			'en' => 'A provisional ballot is for voters who aren\'t on the list at their polling place, including anyone who registers after the October 23 deadline. Your local electoral board reviews it before it\'s counted, and you get a notice saying when and where the board decides. Voted one because you had no ID? Your ID copy or signed ID Confirmation Statement must reach the board by noon on Friday, November 6.',
			'es' => 'Una boleta provisional es para votantes que no aparecen en la lista de su lugar de votación, incluida cualquier persona que se registra después de la fecha límite del 23 de octubre. La junta electoral de tu localidad (electoral board) la revisa antes de contarla, y te dan un aviso con la fecha, la hora y el lugar en que la junta decide. ¿Votaste con una porque no tenías identificación? La copia de tu identificación o tu declaración de confirmación de identidad (ID Confirmation Statement) firmada debe llegar a la junta a más tardar al mediodía del viernes 6 de noviembre.',
			'src' => 'https://www.elections.virginia.gov/registration/same-day-voter-registration/',
			'checked' => '2026-10-28',
		),
		'faq.line' => array(
